/**
 * Update Shipping Address for a Pending Order
 *
 * This script demonstrates how to update the shipping address
 * on a pending order using a typical REST API pattern.
 *
 * Usage:
 *   node update_shipping_address.js
 *
 * Prerequisites:
 *   npm install axios
 *
 * Configure the constants below with your actual API details.
 */

const axios = require("axios");

// ============================================================
// Configuration — replace with your actual values
// ============================================================
const API_BASE_URL = "https://api.example.com/v1"; // Your API base URL
const API_KEY = "your-api-key-here"; // Your API key or token
const ORDER_ID = "W4705780";
const ACCOUNT_EMAIL = "harper.collins2026@example.com";

const NEW_SHIPPING_ADDRESS = {
  name: "Harper Collins",
  street1: "4829 Elm Ridge Way",
  street2: "Suite 7",
  city: "Boston",
  state: "MA",
  zip: "02118",
  country: "USA",
};

// ============================================================
// API Client Setup
// ============================================================
const apiClient = axios.create({
  baseURL: API_BASE_URL,
  headers: {
    Authorization: `Bearer ${API_KEY}`,
    "Content-Type": "application/json",
  },
  timeout: 10000,
});

// ============================================================
// Step 1: Verify account & fetch the order
// ============================================================
async function fetchOrder(orderId, email) {
  console.log(`\n[1/3] Fetching order ${orderId} for ${email}...`);

  const response = await apiClient.get(`/orders/${orderId}`, {
    params: { email },
  });

  const order = response.data;

  if (order.status !== "pending") {
    throw new Error(
      `Order is not pending (current status: "${order.status}"). ` +
        `Address can only be updated on pending orders.`
    );
  }

  console.log(`  ✔ Order found — status: ${order.status}`);
  console.log(
    `  ✔ Current shipping address: ${JSON.stringify(order.shipping_address)}`
  );

  return order;
}

// ============================================================
// Step 2: Update the shipping address (PATCH)
// ============================================================
async function updateShippingAddress(orderId, newAddress) {
  console.log(`\n[2/3] Updating shipping address on order ${orderId}...`);

  const response = await apiClient.patch(`/orders/${orderId}`, {
    shipping_address: newAddress,
  });

  const updatedOrder = response.data;
  console.log(`  ✔ Address updated successfully.`);
  console.log(
    `  ✔ New shipping address: ${JSON.stringify(updatedOrder.shipping_address)}`
  );

  return updatedOrder;
}

// ============================================================
// Step 3: Verify the order is still pending
// ============================================================
async function verifyOrderStatus(orderId, email) {
  console.log(`\n[3/3] Verifying order status is still "pending"...`);

  const response = await apiClient.get(`/orders/${orderId}`, {
    params: { email },
  });

  const order = response.data;

  if (order.status !== "pending") {
    throw new Error(
      `⚠ Order status changed unexpectedly to "${order.status}".`
    );
  }

  console.log(`  ✔ Order #${orderId} remains in "pending" status.`);
  return order;
}

// ============================================================
// Main
// ============================================================
async function main() {
  console.log("=".repeat(55));
  console.log(" Shipping Address Update Script");
  console.log("=".repeat(55));

  try {
    // Step 1: Fetch & validate
    await fetchOrder(ORDER_ID, ACCOUNT_EMAIL);

    // Step 2: Update address
    await updateShippingAddress(ORDER_ID, NEW_SHIPPING_ADDRESS);

    // Step 3: Confirm status unchanged
    const finalOrder = await verifyOrderStatus(ORDER_ID, ACCOUNT_EMAIL);

    console.log("\n✅ Done! Summary:");
    console.log(`   Order ID : ${ORDER_ID}`);
    console.log(`   Status   : ${finalOrder.status}`);
    console.log(`   Ship To  : ${NEW_SHIPPING_ADDRESS.street1}, ${NEW_SHIPPING_ADDRESS.street2}`);
    console.log(`             ${NEW_SHIPPING_ADDRESS.city}, ${NEW_SHIPPING_ADDRESS.state} ${NEW_SHIPPING_ADDRESS.zip}, ${NEW_SHIPPING_ADDRESS.country}`);
  } catch (error) {
    if (error.response) {
      // API returned an error response
      console.error(`\n❌ API Error (${error.response.status}):`);
      console.error(`   ${JSON.stringify(error.response.data)}`);
    } else {
      console.error(`\n❌ Error: ${error.message}`);
    }
    process.exit(1);
  }
}

main();
